__d(function(g,r,i,_a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LESSONS",{enumerable:!0,get:function(){return t}}),e.nextLesson=function(n){const o=n.areas??[],s=s=>{const l=t.find(t=>t.n===s);return!!l&&a(l,o,n.labels??[])},l=[];n.painUp&&l.push(4);l.push(...t.filter(t=>t.dx).map(t=>t.n),...t.filter(t=>t.areas).map(t=>t.n)),n.mind.includes('worry')&&l.push(1,3);n.mind.includes('avoid')&&l.push(5,7);(n.mind.includes('sleep')||n.mind.includes('down'))&&l.push(6,15);return l.push(...n.phase>=3?[8,7,5,12]:2===n.phase?[5,7,12,1,2]:[1,2,4],...t.map(t=>t.n)),l.find(t=>s(t)&&!n.seen.includes(t))??null},Object.defineProperty(e,"lessonFits",{enumerable:!0,get:function(){return n}});const t=[{n:1,title:"Hurt doesn't always mean harm",body:"Pain is your body's alarm system, and alarms can be sensitive. Feeling some pain during exercise usually means the system is protective, not that you're doing damage. Our rule: pain during exercise up to 3 out of 10 is fine, as long as you're back to normal by the next morning."},{n:2,title:"Pain has a volume knob",body:"Your nervous system decides how loud pain is, based on more than the tissue. Stress, poor sleep, worry and past flares can turn it up. The good news: movement, sleep, confidence and time turn it back down. That's what your plan is built to do."},{n:3,title:"Scans find things in people with no pain",body:"Disc bulges, rotator cuff tears and arthritis show up on plenty of scans of people who feel fine, and they get more common with age, like gray hair. A finding on a scan doesn't mean it's the cause of your pain, and it doesn't mean you can't get better."},{n:4,title:"Flare plan: ease off, don't stop",body:"Flares happen and they usually settle in a few days. Cut your exercise back by about half, keep moving gently, and get your sleep. Don't rest it completely. If it's not settling after a week, or something new shows up, tell me in your check in."},{n:5,title:"Motion is lotion",body:"Joints, discs and tendons get their nutrition from movement, and resting too long makes everything more sensitive. Gentle movement is one of the fastest ways to calm pain down. Your Calm it moves are picked to feel good, not to push through."},{n:6,title:"Sleep and stress change pain",body:"One bad night can make pain feel worse the next day, and steady stress keeps the volume knob turned up. Protect your sleep: same bedtime, a dark cool room, screens off an hour before. A short walk or slow breathing helps on stressful days."},{n:7,title:"Pace by plan, not by feel",body:"On good days it's tempting to do too much, then pay for it. Instead, set an amount you can do on a bad day and grow it a little each week, about 10 percent. Steady beats heroic, and it's how you build capacity without flares."},{n:8,title:"Setbacks are part of the road",body:"Recovery isn't a straight line. A bad week after a few good ones is normal and doesn't erase your progress. Look at the trend over a month, not the day. You now know how to handle a flare, and that's what keeps you in control long term."},{n:9,title:"Disc changes are normal with age",body:"In people with no back pain at all, about a third of 20 year olds show disc degeneration on a scan, and nearly everyone does by 80. These changes are closer to wrinkles on the inside than to an injury.",areas:["Low back","Mid back","Neck"],source:"Brinjikji et al. 2015, American Journal of Neuroradiology"},{n:10,title:"Herniated discs often shrink on their own",body:"A disc herniation is not permanent for most people. In a review of studies that scanned people again later, the biggest herniations shrank the most often: 96 percent of the largest type and 70 percent of the next largest got smaller without surgery.",areas:["Low back"],source:"Chiu et al. 2015, Clinical Rehabilitation"},{n:11,title:"Meniscus tears show up in knees that feel fine",body:"In a large study of middle aged and older adults, 61 percent of the people who had a meniscus tear on their scan had no knee pain, aching or stiffness. A tear on a report is not always the reason a knee hurts.",areas:["Knee"],source:"Englund et al. 2008, New England Journal of Medicine"},{n:12,title:"Strength training lowers injury risk",body:"Across 25 trials in athletes, strength training cut sports injuries to less than a third, and overuse injuries were almost halved. Stretching alone showed no benefit. Getting stronger is one of the best protections there is.",source:"Lauersen et al. 2014, British Journal of Sports Medicine"},{n:13,title:"Walking helps keep back pain away",body:"In a trial of adults who had just recovered from back pain, a walking and education program meant a typical wait of 208 days before the next episode, compared with 112 days without it.",areas:["Low back"],source:"Pocovi et al. 2024, The Lancet"},{n:14,title:"Running doesn't wear out your knees",body:"In a review covering about 115,000 people, 3.5 percent of recreational runners had hip or knee arthritis, compared with 10.2 percent of people who didn't run. Joints adapt to the load you give them.",areas:["Knee","Hip"],source:"Alentorn-Geli et al. 2017, Journal of Orthopaedic and Sports Physical Therapy"},{n:15,title:"Short sleep raises injury risk",body:"In a study of teenage athletes, those who slept less than 8 hours a night were 1.7 times more likely to get injured than those who slept 8 or more. Sleep is when your body does its repair work.",source:"Milewski et al. 2014, Journal of Pediatric Orthopaedics"},{n:16,title:"Pain is a protector, not a damage meter",body:"Pain is your nervous system's way of protecting you. It turns up when your body senses threat, and that doesn't always match how much tissue damage there is. A paper cut hurts a lot. A big bruise can show up with no memory of the hit.",source:"Louw et al. 2016, Physiotherapy Theory and Practice"},{n:17,title:"Your back is built strong",body:"Your spine is one of the sturdiest structures in your body. It's made to bend, twist and carry load. Back pain is common and rarely means something is seriously wrong. Moving it, loading it and trusting it again is usually the way forward.",areas:["Low back","Mid back"],source:"O'Sullivan et al. 2020, British Journal of Sports Medicine"},{n:18,title:"Rotator cuff tears get more common with age",body:"Rotator cuff changes become more common with every decade, and many people who have one never notice it. Shoulders can work well and feel good with a tear, which is why strength and movement come first.",areas:["Shoulder"],source:"Teunis et al. 2014, Journal of Shoulder and Elbow Surgery"},{n:19,title:"Cracking your knuckles is fine",body:"The pop is gas moving inside the joint, not bone on bone. A study comparing people who crack their knuckles with people who don't found no link to hand arthritis.",source:"deWeber et al. 2011, Journal of the American Board of Family Medicine"},{n:20,title:"Some pain during exercise is okay",body:"Exercise doesn't have to be pain free to help. In a review of trials on long lasting muscle and joint pain, programs that allowed some pain did slightly better in the short term than pain free ones, and the same after that. That's why your plan uses a pain limit, not a pain ban.",source:"Smith et al. 2017, British Journal of Sports Medicine"},{n:21,title:"Stretching doesn't prevent soreness",body:"Stretching before or after a workout makes almost no difference to how sore you feel the next day. Soreness after new exercise is normal and fades in a few days as your body adapts.",source:"Herbert et al. 2011, Cochrane Database of Systematic Reviews"},{n:22,title:"Tendons like load, not rest",body:"Tendons need load to recover. In a trial of Achilles tendon pain, people who kept up their sport within a pain limit improved just as much as those who rested from it, with no harm from the extra loading.",areas:["Tendon"],source:"Silbernagel et al. 2007, American Journal of Sports Medicine"},{n:23,title:"There is no one perfect posture",body:"Research has not found a single correct way to sit or stand that prevents pain. Comfortable, relaxed positions are fine. What helps most is changing position often. Your best posture is your next one.",areas:["Low back","Mid back","Neck"],source:"Slater et al. 2019, Journal of Orthopaedic and Sports Physical Therapy"},{n:24,title:"A rounded back when lifting isn't the enemy",body:"A review of the research found that bending your back when you lift was not a risk factor for back pain. Build up to heavy lifts a little at a time.",areas:["Low back"],source:"Saraceni et al. 2020, Journal of Orthopaedic and Sports Physical Therapy"},{n:25,title:"Staying active beats bed rest",body:"For a fresh episode of back pain, people advised to stay active did a little better on pain and function than people told to rest in bed. Short rests are fine. Days in bed tend to slow things down.",areas:["Low back"],source:"Dahm et al. 2010, Cochrane Database of Systematic Reviews"},{n:26,title:"A real warm up is worth it",body:"In soccer players, a structured warm up of running, strength and balance drills led to about 39 percent fewer injuries across four trials. Ten minutes of the right prep pays off.",source:"Thorborg et al. 2017, British Journal of Sports Medicine"},{n:27,title:"Surgery did no better than a placebo operation",body:"In a trial of 313 people with pain at the top of the shoulder, shaving the bone to make more room did no better than a placebo operation. That's why loading and strengthening the shoulder comes first.",areas:["Shoulder"],dx:"rotator cuff tendinopathy|subacromial",source:"Beard et al. 2018, The Lancet"},{n:28,title:"Strength work helps neck pain, stretching alone doesn't",body:"A review of trials found that strengthening the neck, shoulder blades and arms eased long lasting neck pain. Stretching alone did not. That's why your plan builds strength.",areas:["Neck"],source:"Gross et al. 2015, Cochrane Database of Systematic Reviews"},{n:29,title:"Exercise eases hip arthritis pain",body:"In a review of 10 trials, exercise lowered hip arthritis pain by about 8 points out of 100 and improved function by about 7. The gains were still there three to six months after the program ended.",areas:["Hip"],dx:"hip osteoarthritis",source:"Cochrane review of exercise for hip osteoarthritis, 2026 update"},{n:30,title:"Exercise is a proven treatment for knee arthritis",body:"Across 44 trials and more than 3,500 people, exercise gave a moderate drop in knee arthritis pain and a moderate gain in what people could do. Arthritis on a scan doesn't mean your knee can't get stronger.",areas:["Knee"],dx:"knee osteoarthritis",source:"Fransen et al. 2015, Cochrane Database of Systematic Reviews"},{n:31,title:"Meniscus surgery did no better than a placebo operation",body:"In a trial of 146 people with a wear and tear meniscus tear and no arthritis, trimming the meniscus did no better than a placebo operation after 12 months. A tear from a sudden injury, or a knee that locks, is a different situation, so ask me about yours.",areas:["Knee"],dx:"degenerative meniscus",source:"Sihvonen et al. 2013, New England Journal of Medicine"},{n:32,title:"The quick fix for tennis elbow can come back",body:"In a trial of 165 people with tennis elbow, 54 percent of those given a steroid injection had it come back within a year, compared with 12 percent given a placebo injection. Building the tendon back up takes patience.",areas:["Elbow"],dx:"tennis elbow|lateral elbow tend",source:"Coombes et al. 2013, JAMA"},{n:33,title:"Heel raises work faster than stretching",body:"In a trial of 48 people with plantar fasciitis, slow heavy heel raises gave much better results at 3 months than stretching. By 12 months the two groups were even, so strength work gets you there sooner.",areas:["Ankle or foot"],dx:"plantar fasci",source:"Rathleff et al. 2015, Scandinavian Journal of Medicine and Science in Sports"},{n:34,title:"Exercise beat an injection for gluteal tendon pain",body:"In a trial of 204 people with gluteal tendon pain, 79 percent of those who did education and exercise rated themselves better a year later, compared with 58 percent after a steroid injection and 52 percent of those who waited.",areas:["Hip"],dx:"gluteal tendinopathy",source:"Mellor et al. 2018, BMJ"},{n:35,title:"Rehab first is a real option after an ACL tear",body:"In a trial of 121 active young adults with a fresh ACL tear, everyone did rehab and half had surgery early. In the other half, 61 percent had not needed surgery two years later, and knee scores were the same in both groups. Surgery is still the right call for some knees, so that's a decision for you, me and your surgeon.",areas:["Knee"],dx:"ACL",source:"Frobell et al. 2010, New England Journal of Medicine"},{n:36,title:"Sciatica from a disc usually recovers",body:"In a trial of 283 people with sciatica from a disc, early surgery eased leg pain faster. After a year, 95 percent had recovered in both groups, whether they had surgery early or waited and had it only if needed.",areas:["Low back"],dx:"radiculopathy|radiating|sciatic",source:"Peul et al. 2007, New England Journal of Medicine"},{n:37,title:"Neck scans show bulges in necks that feel fine",body:"In a study of 1,211 people with no neck symptoms, about 88 percent had a bulging disc on their neck scan. Findings like that are common in necks that feel fine.",areas:["Neck"],source:"Nakashima et al. 2015, Spine"},{n:38,title:"Rehab lowers the odds of spraining it again",body:"A review of the research found that rehab exercise lowered the odds of spraining the same ankle again by about 40 percent, and a brace or tape lowered them further. Finishing your balance and strength work is what protects it.",areas:["Ankle or foot"],dx:"^ankle sprain|chronic ankle instability",source:"Doherty et al. 2017, British Journal of Sports Medicine"},{n:39,title:"Hip strength helps kneecap pain",body:"A review of trials found that exercise eases kneecap pain and improves what people can do, and that adding hip exercises to knee exercises may ease pain a little more.",areas:["Knee"],dx:"patellofemoral",source:"van der Heijden et al. 2015, Cochrane Database of Systematic Reviews"},{n:40,title:"Grip strength says a lot about your health",body:"In a study of about 140,000 adults in 17 countries, every 5 kilograms less grip strength went with a 16 percent higher risk of dying during the study. Strength is one of the best markers of health we have.",source:"Leong et al. 2015, The Lancet"},{n:41,title:"A little strength training goes a long way",body:"Across 16 studies, people who did muscle strengthening exercise had a 10 to 17 percent lower risk of dying from any cause. The biggest benefit showed up at just 30 to 60 minutes a week.",source:"Momma et al. 2022, British Journal of Sports Medicine"},{n:42,title:"You don't need 10,000 steps",body:"In a review of 15 studies and about 47,000 adults, more daily steps went with a lower risk of dying, and the benefit levelled off at 6,000 to 8,000 steps for people 60 and older and 8,000 to 10,000 for younger adults.",source:"Paluch et al. 2022, The Lancet Public Health"},{n:43,title:"Balance is trainable",body:"Across 108 trials and more than 23,000 older adults, exercise cut the rate of falls by about 23 percent. Balance and everyday movement exercises worked best.",source:"Sherrington et al. 2019, Cochrane Database of Systematic Reviews"},{n:44,title:"Exercise eases hand arthritis",body:"In a review of seven trials, hand exercise eased pain and finger stiffness in people with hand arthritis, with very few side effects. Stiff, sore joints still do better when they move.",areas:["Wrist or hand"],dx:"osteoarthritis",source:"\xd8ster\xe5s et al. 2017, Journal of Rheumatology"},{n:45,title:"Tennis elbow: fast relief isn't the same as better",body:"In a trial of about 185 people with tennis elbow, 92 percent felt better six weeks after a steroid injection. A year later that had dropped to 69 percent, while 91 percent of the physical therapy group and 83 percent of those who simply waited were better.",areas:["Elbow"],dx:"tennis elbow|lateral elbow tend",source:"Smidt et al. 2002, The Lancet"},{n:46,title:"Balance training protects your ankles",body:"Across seven trials and more than 3,700 athletes, balance training lowered the risk of an ankle sprain by about 35 percent, and it worked just as well in people who had sprained an ankle before.",areas:["Ankle or foot"],dx:"^ankle sprain|chronic ankle instability",source:"Schiftan et al. 2015, Journal of Science and Medicine in Sport"},{n:47,title:"Achilles tendons respond to heavy, slow loading",body:"In a trial of 58 people with Achilles tendon pain, both slow heavy strength training and heel drops improved pain and function in 12 weeks, and the gains were still there a year later.",areas:["Ankle or foot"],dx:"^achilles tendinopathy",source:"Beyer et al. 2015, American Journal of Sports Medicine"},{n:48,title:"The right exercises can take surgery off the table",body:"In a trial of people on a waiting list for shoulder surgery, 20 percent of those given a specific strengthening program still chose surgery, compared with 63 percent of those given general exercises.",areas:["Shoulder"],dx:"rotator cuff tendinopathy|subacromial",source:"Holmgren et al. 2012, BMJ"},{n:49,title:"Most cuff tears that came on gradually do well with therapy",body:"In a study of 381 people with a full thickness rotator cuff tear that was not from an injury, about three quarters had not had surgery two years after starting physical therapy.",areas:["Shoulder"],dx:"rotator cuff tear",source:"Kuhn et al. 2013, Journal of Shoulder and Elbow Surgery"},{n:50,title:"Hamstrings heal faster when you lengthen them",body:"In a trial of 75 elite soccer players with a hamstring strain, those who did lengthening exercises were back in about 28 days, compared with 51 days for conventional exercises.",areas:["Hip"],dx:"hamstring strain",source:"Askling et al. 2013, British Journal of Sports Medicine"},{n:51,title:"Active training beats passive treatment for groin pain",body:"In a trial of 68 athletes with long lasting adductor groin pain, 79 percent of those who did active strengthening got back to their sport without pain. In the group given passive treatment and stretching, only 4 athletes did.",areas:["Hip"],dx:"adductor tendinopathy",source:"H\xf6lmich et al. 1999, The Lancet"},{n:52,title:"Neck exercise can cut headaches",body:"In a trial of 200 people with headaches coming from the neck, specific neck exercises reduced how often the headaches came and how strong they were, and the benefit was still there a year later.",areas:["Neck"],dx:"headache",source:"Jull et al. 2002, Spine"},{n:53,title:"For patellar tendons, loading lasts and injections fade",body:"In a trial of 39 men with patellar tendon pain, everyone improved after 12 weeks. Six months on, those who did loading exercises had kept their gains, while those who had a steroid injection had lost them.",areas:["Knee"],dx:"patellar tendinopathy",source:"Kongsgaard et al. 2009, Scandinavian Journal of Medicine and Science in Sports"},{n:54,title:"It's never too late to get stronger",body:"In a study of nine nursing home residents aged 87 to 96, eight weeks of strength training raised their leg strength by 174 percent on average. Muscle responds to training at every age.",source:"Fiatarone et al. 1990, JAMA"},{n:55,title:"Lifting builds bone",body:"In a trial of 101 women past menopause with low bone mass, eight months of supervised heavy lifting left their spine bone density about 4 percent better than the group that didn't lift. Bones get stronger when you load them.",source:"Watson et al. 2018, Journal of Bone and Mineral Research"},{n:56,title:"Movement helps your mood",body:"A review covering more than 1,000 trials and 128,000 people found that physical activity eased symptoms of depression, anxiety and distress. Your sessions are doing more than fixing a joint.",source:"Singh et al. 2023, British Journal of Sports Medicine"},{n:57,title:"A night splint is a fair first step",body:"In a trial of 176 people with carpal tunnel syndrome, 54 percent were better after three months of night splinting and 80 percent after surgery. A splint is a fair place to start, and surgery works well when it isn't enough.",areas:["Wrist or hand"],dx:"carpal tunnel",source:"Gerritsen et al. 2002, JAMA"},{n:58,title:"Strength work plus arch supports beats supports alone",body:"In a trial of 36 people with posterior tibial tendon pain, everyone wore arch supports. Those who added tendon strengthening had less pain and better function after 12 weeks than those who only stretched.",areas:["Ankle or foot"],dx:"posterior tibial",source:"Kulig et al. 2009, Physical Therapy"},{n:59,title:"One exercise halves hamstring injuries",body:"Across 15 studies and more than 8,400 athletes, programs that included the Nordic hamstring exercise cut hamstring injuries by 51 percent. Strong hamstrings at long lengths are protected hamstrings.",areas:["Hip"],dx:"hamstring",source:"van Dyk et al. 2019, British Journal of Sports Medicine"},{n:60,title:"Strong adductors prevent groin trouble",body:"In a trial of 652 soccer players, one adductor strengthening exercise added to training lowered the risk of groin problems by 41 percent.",areas:["Hip"],dx:"adductor|athletic pubalgia",source:"Har\xf8y et al. 2019, British Journal of Sports Medicine"},{n:61,title:"Strength training improves flexibility too",body:"A review of 11 studies found that strength training improved flexibility as much as stretching did. You don't have to choose between strong and mobile.",source:"Afonso et al. 2021, Healthcare"},{n:62,title:"Exercise matched pain pills for arthritis",body:"A review of 152 trials and more than 17,000 people with knee or hip arthritis found that exercise eased pain and improved function about as much as common pain relievers, at 4, 8 and 24 weeks.",areas:["Knee","Hip"],dx:"osteoarthritis",source:"Weng et al. 2023, British Journal of Sports Medicine"},{n:63,title:"Shoulder scans find things in shoulders that feel fine",body:"In a study of 51 men aged 40 to 70 with no shoulder symptoms at all, 96 percent had at least one abnormal finding on a shoulder ultrasound. A finding on your scan is not always the cause of your pain.",areas:["Shoulder"],source:"Girish et al. 2011, American Journal of Roentgenology"},{n:64,title:"Frozen shoulder gets better, slowly",body:"In a study that followed 223 people with frozen shoulder for about four years, 59 percent ended up with a normal or near normal shoulder. Of those who still had symptoms, 94 percent said they were mild.",areas:["Shoulder"],dx:"adhesive capsulitis",source:"Hand et al. 2008, Journal of Shoulder and Elbow Surgery"},{n:65,title:"Knowing what irritates the nerve is most of the fix",body:"In a trial of people with cubital tunnel syndrome, about 9 in 10 improved within six months after learning which positions were irritating the nerve and avoiding them. Splints and nerve glides added nothing on top of that.",areas:["Elbow","Wrist or hand"],dx:"cubital tunnel",source:"Svernl\xf6v et al. 2009, Journal of Hand Surgery, European Volume"},{n:66,title:"Mid back scans show disc changes in people with no pain",body:"In a study of 90 people with no mid back symptoms, 73 percent had findings on their scan and 37 percent had a herniated disc. Changes like these are common in backs that feel fine.",areas:["Mid back"],source:"Wood et al. 1995, Journal of Bone and Joint Surgery"},{n:67,title:"Tendons adapt to heavy loads",body:"A review of 27 studies found that tendons get stiffer and stronger with training, and that how heavy the load was mattered more than the type of exercise. That's why your tendon work gets heavier over time.",areas:["Tendon"],source:"Bohm et al. 2015, Sports Medicine Open"},{n:68,title:"Most back pain settles",body:"Most episodes of low back pain improve substantially within six weeks. About a third of people have another episode within a year, and that doesn't mean you're back at square one. You'll know what to do next time.",areas:["Low back"],source:"Hartvigsen et al. 2018, The Lancet"},{n:69,title:"The lowering phase does the work",body:"In a trial of 21 people with long standing tennis elbow, adding a slow lowering wrist exercise to standard treatment improved arm function by 76 percent, compared with 13 percent with standard treatment alone.",areas:["Elbow"],dx:"tennis elbow|lateral elbow tend",source:"Tyler et al. 2010, Journal of Shoulder and Elbow Surgery"},{n:70,title:"Treatment gets you there sooner",body:"In a trial of 198 people with tennis elbow, physical therapy with hands on work and exercise beat waiting it out over the first six weeks, and beat a steroid injection after that.",areas:["Elbow"],dx:"tennis elbow|lateral elbow tend",source:"Bisset et al. 2006, BMJ"},{n:71,title:"A thumb splint pays off over months",body:"In a trial of 112 people with arthritis at the base of the thumb, a splint worn at night made no difference to pain after one month. After a year, pain and hand function were clearly better than with usual care.",areas:["Wrist or hand"],dx:"thumb cmc",source:"Rannou et al. 2009, Annals of Internal Medicine"},{n:72,title:"Hands on treatment can match surgery",body:"In a trial of 120 women with carpal tunnel syndrome, three sessions of hands on physical therapy eased pain faster than surgery over the first three months. At six and twelve months the two groups were doing about the same.",areas:["Wrist or hand"],dx:"carpal tunnel",source:"Fern\xe1ndez-de-las-Pe\xf1as et al. 2015, The Journal of Pain"}],a=(t,a,n)=>(!t.areas||t.areas.some(t=>a.includes(t)))&&(!t.dx||n.some(a=>new RegExp(t.dx,'i').test(a)));const n=(n,o,s=[])=>{const l=t.find(t=>t.n===n);return!!l&&a(l,o,s)}},857,[]);
