__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL_UPDATED",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"privacy",{enumerable:!0,get:function(){return u}}),Object.defineProperty(e,"telehealth",{enumerable:!0,get:function(){return h}});const o='November 12, 2026',t='Guidance Rehab and Performance',s='hello@guidancerehab.com',n={title:'Terms of Service',intro:`These terms cover your use of the ${t} website, app, membership and visits. By creating an account, booking or paying, you agree to them.`,sections:[{h:'Who we are',p:[`${t} is a cash pay physical therapy practice in Las Vegas, Nevada. Care is provided by Dr. Nolan Daniels, PT, DPT, a physical therapist licensed in Nevada.`]},{h:'Not for emergencies',p:['Guidance is not an emergency service. Messages are answered within one business day. If you have a medical emergency, call 911 or go to the nearest emergency room.']},{h:'Physical therapy, not a guarantee',p:['Your program is based on your assessment and the information you share. Results vary and are not guaranteed. Stop any exercise that causes sharp pain, dizziness, chest pain, numbness or anything unusual and contact your PT. You agree to share accurate information about your health so your care can be safe.']},{h:'Membership and billing',p:['Membership is billed monthly or yearly in advance through Stripe until you cancel. It includes messaging, your program, and one first visit at the gym or by video (as a house call, the first visit is $60). Visits after that are booked separately at member prices.','Members who joined before November 2026 keep their original plan, which includes one 60 minute visit each calendar month at the gym or by video (an unused visit carries over one month, then expires; using it at your home adds a $40 travel fee), until they switch plans or cancel.','Founding pricing is for the first 10 members. Founding members keep their founding rate as long as the membership stays active, including after switching plans. If you cancel and rejoin later, current pricing applies.','Switching from an original plan to the current membership takes effect on your next bill.','You can cancel anytime from the Membership screen. Canceling stops future billing; you keep access until the end of the period you already paid for. Payments already made are not refunded except where required by law.','You can pause for up to one month per year. Your spot and rate are held during the pause.']},{h:'Visits, cancellations and no shows',p:['Visits can be booked at least 12 hours ahead. You can cancel or reschedule in the app up to 12 hours before your visit.','Cancellations inside 12 hours or missed visits may be charged in full, or count as your included visit for the month on an original plan.','House visits are available in the Las Vegas valley. Please provide a safe space with room to move.']},{h:'Insurance',p:['Guidance does not bill insurance. On request we provide a superbill you can submit yourself for possible out of network reimbursement. Reimbursement is up to your plan and is not guaranteed. HSA and FSA cards are usually accepted; check with your plan.']},{h:'Your account',p:['Keep your email secure, since sign in codes are sent there. Do not share your account. We may suspend accounts that are abused or used to harass anyone.']},{h:'Content',p:['Programs, videos and materials are for your personal use while you are a client. Please do not resell or publicly post them.']},{h:'Liability',p:['To the fullest extent the law allows, our total liability for any claim related to the service is limited to what you paid in the 3 months before the claim. Nothing here limits liability that cannot be limited under Nevada law.']},{h:'Changes and contact',p:[`We may update these terms and will change the date at the top. Questions: ${s}. These terms are governed by Nevada law.`]}]},u={title:'Privacy Policy',intro:`${t} takes your privacy seriously. This explains what we collect, why, and your choices.`,sections:[{h:'What we collect',p:['Account details: name, email and optional phone.','Care details you choose to share: goals, equipment, weekly check ins (pain, soreness, effort, notes), messages, exercise completions, visit bookings and progress measures your PT records.','Payment details are handled by Stripe. We never see or store your full card number.',`Free body check: where it hurts, how it started, your age range, any health history and safety check answers you tick, and your goal. We use it to build your results and, if you book, to prepare for your call. If you ask us to email your results, we send them plus up to 2 follow up emails with tips, each with an unsubscribe link. A copy without your name or contact details is kept for 90 days so we can improve the check, then deleted. Ask us to delete it anytime at ${s}.`,'Website visits: we record page views and button taps on this site to learn what is useful. No ads and no third party trackers.','Apple Health (iPhone app, only if you turn it on): your daily step count, read only. It is used for your care, to see how activity relates to your pain, and is never used for advertising or shared with anyone else. Turn it off anytime in your Profile, which also deletes your step history with us.']},{h:'How we use it',p:['To provide and adjust your care, schedule visits, send sign in codes, visit reminders and reminders about your program, process payments, and run the business. We do not sell your information and we do not use it for advertising.']},{h:'Who we share it with',p:['Service providers that run the app on our behalf: Supabase (secure database and sign in), Stripe (payments), Resend (email), Wibbi (exercise programs and demo videos, which receives your name and email so your PT can build your program), Doxy.me (video visits) and GitHub Pages (website hosting). They only use your information to provide their service to us.','Your PT sometimes uses an AI writing assistant (Anthropic) to help draft replies to your messages. To do that it receives your first name, your program, your body check results and your recent messages. Your PT reads and approves every message before it is sent to you. Questions about using the app may be answered right away by an automated AI assistant, which is labeled in the conversation. It does not give advice about your body; those questions go to your PT.','We share information if required by law, or to protect someone\'s safety.']},{h:'Health information',p:['Your PT keeps clinical records as required for licensed physical therapists in Nevada. Please do not send detailed medical history through the intro call form; we cover it during your visit. Access to your information in the app is limited to you and your PT.']},{h:'Security',p:['Information is encrypted in transit, and each member can only see their own records. No system is perfectly secure, so please contact us right away if you think your account was accessed without permission.']},{h:'Your choices',p:[`You can view your information in the app, ask us to correct it, or ask us to delete your account at ${s}. Some records must be kept for a period required by law.`]},{h:'Your Nevada health data rights',p:['We collect consumer health data only with your consent, such as when you agree before starting the body check, and only to provide the service you asked for. We never sell it.',`You can ask to see what health data we have about you, ask us to delete it, or withdraw your consent at any time by emailing ${s}. We respond within 45 days. Withdrawing consent stops future collection; it does not undo care already provided.`]},{h:'Children',p:['Guidance is for adults 18 and over. Minors may be seen only with a parent or guardian who creates and manages the account.']},{h:'Credits',p:['Body figure images by kjpargeter on Freepik.']},{h:'Contact',p:[`Questions about privacy: ${s}.`]}]},h={title:'Telehealth Consent',intro:'Some of your care happens by video and through the app. Please read this before your first remote visit.',sections:[{h:'What telehealth means here',p:['Video visits through Doxy.me, program updates, messages, photos and form check videos reviewed by your physical therapist.']},{h:'Benefits and limits',p:['Telehealth saves travel and lets your PT adjust your plan more often.','Your PT cannot touch or fully examine you by video, so some problems may need an in person visit. Your PT may recommend an in person visit or a referral to another provider at any time.']},{h:'Location and licensing',p:['Video care is provided to people located in Nevada at the time of the visit, where your PT is licensed. Tell your PT if you will be outside Nevada.']},{h:'Privacy and technology',p:['Video visits use Doxy.me, a telehealth platform built for healthcare. Use a private space and a secure connection. If a call drops, your PT will try to reconnect or call you.']},{h:'Safety',p:['Have a clear space to move, and someone nearby if you have fall risk. Stop if anything feels unsafe. In an emergency, call 911.']},{h:'Your rights',p:['You may decline or stop telehealth at any time and choose in person care instead.']},{h:'Consent',p:['By checking the consent box at checkout or booking a video visit, you confirm you have read this, had the chance to ask questions, and agree to receive care by telehealth.']}]}},984,[]);
